"""Detection metrics with explicit definitions.

Positive class: a case whose expected outcome is *not* ALLOW (``deny`` or ``review``), i.e.
something that must not run unattended. A prediction is positive when the validator's decision
is not ALLOW. On top of the binary view, ``exact_match_rate`` measures how often the
three-way decision (allow/review/deny) matches exactly.

Two further distinctions are reported because a denial is not the same as a correct
security detection:

* ``tier``: ``internal`` (written or generated by this project) versus ``independent``
  (``external:`` provenance: authored outside the project). They are never pooled in headline
  figures.
* ``basis`` of a flagged decision: ``unsupported`` (the SQL could not be parsed or is a
  statement type outside scope) versus ``policy`` (a policy rule decided).
"""

from __future__ import annotations

import math
from collections import defaultdict
from collections.abc import Iterable
from dataclasses import dataclass
from typing import Any

from sqlguard_ninja.core.findings import Decision


@dataclass(frozen=True)
class CaseOutcome:
    id: str
    category: str
    dialect: str
    provenance: str
    expected: Decision
    actual: Decision
    latency_ms: float
    error: str | None = None
    in_capability: bool = True
    reasons: tuple[str, ...] = ()

    @property
    def tier(self) -> str:
        return dataset_tier(self.provenance)

    @property
    def basis(self) -> str:
        """Why a flagged case was flagged: unsupported input or a policy rule."""
        if not self.flagged:
            return "none"
        if self.reasons and all(r.startswith(UNSUPPORTED_PREFIXES) for r in self.reasons):
            return "unsupported"
        return "policy"

    @property
    def unsafe(self) -> bool:
        return self.expected is not Decision.ALLOW

    @property
    def flagged(self) -> bool:
        return self.actual is not Decision.ALLOW

    @property
    def kind(self) -> str:
        if self.unsafe and self.flagged:
            return "tp"
        if self.unsafe:
            return "fn"
        if self.flagged:
            return "fp"
        return "tn"


UNSUPPORTED_PREFIXES = ("parse.", "statement.unsupported")
INDEPENDENT_PREFIXES = ("external:",)


def dataset_tier(provenance: str) -> str:
    """``independent`` only for cases authored outside the project; everything else internal."""
    return "independent" if provenance.startswith(INDEPENDENT_PREFIXES) else "internal"


def wilson_interval(successes: int, total: int, z: float = 1.959964) -> list[float] | None:
    """95% Wilson score interval for a proportion (None when ``total`` is 0)."""
    if total == 0:
        return None
    p = successes / total
    denom = 1 + z * z / total
    centre = (p + z * z / (2 * total)) / denom
    half = z * math.sqrt(p * (1 - p) / total + z * z / (4 * total * total)) / denom
    return [round(max(0.0, centre - half), 4), round(min(1.0, centre + half), 4)]


def _ratio(num: int, den: int) -> float | None:
    return None if den == 0 else round(num / den, 4)


def percentile(values: list[float], pct: float) -> float | None:
    """Nearest-rank percentile (deterministic, no interpolation)."""
    if not values:
        return None
    ordered = sorted(values)
    rank = max(1, math.ceil(pct / 100 * len(ordered)))
    return round(ordered[rank - 1], 4)


def summarise(outcomes: Iterable[CaseOutcome]) -> dict[str, Any]:
    items = list(outcomes)
    counts = {"tp": 0, "fp": 0, "tn": 0, "fn": 0}
    for o in items:
        counts[o.kind] += 1
    tp, fp, tn, fn = counts["tp"], counts["fp"], counts["tn"], counts["fn"]
    latencies = [o.latency_ms for o in items]
    recall, precision = _ratio(tp, tp + fn), _ratio(tp, tp + fp)
    f1 = (
        round(2 * precision * recall / (precision + recall), 4)
        if recall is not None and precision is not None and (precision + recall) > 0
        else None
    )
    total_ms = sum(latencies)
    flagged = [o for o in items if o.flagged]
    return {
        "cases": len(items),
        "unsafe_cases": tp + fn,
        "safe_cases": tn + fp,
        **counts,
        "recall": recall,
        "precision": precision,
        "f1": f1,
        "false_positive_rate": _ratio(fp, fp + tn),
        "false_negative_rate": _ratio(fn, fn + tp),
        "exact_match_rate": _ratio(sum(o.expected is o.actual for o in items), len(items)),
        "confidence_95": {
            "method": "wilson",
            "recall": wilson_interval(tp, tp + fn),
            "precision": wilson_interval(tp, tp + fp),
            "false_positive_rate": wilson_interval(fp, fp + tn),
        },
        "flag_basis": {
            "policy": sum(o.basis == "policy" for o in flagged),
            "unsupported": sum(o.basis == "unsupported" for o in flagged),
        },
        "errors": sum(o.error is not None for o in items),
        "throughput_per_s": round(len(items) / (total_ms / 1000), 1) if total_ms > 0 else None,
        "latency_ms": {
            "p50": percentile(latencies, 50),
            "p95": percentile(latencies, 95),
            "p99": percentile(latencies, 99),
            "max": round(max(latencies), 4) if latencies else None,
        },
    }


def grouped(outcomes: list[CaseOutcome], attr: str) -> dict[str, dict[str, Any]]:
    groups: dict[str, list[CaseOutcome]] = defaultdict(list)
    for o in outcomes:
        key = getattr(o, attr)
        if attr == "provenance":
            key = key.split(":")[0] if not key.startswith("generated:") else key.split("@")[0]
        groups[key].append(o)
    return {k: summarise(v) for k, v in sorted(groups.items())}


def compute_metrics(outcomes: list[CaseOutcome], examples: int = 15) -> dict[str, Any]:
    capable = [o for o in outcomes if o.in_capability]
    return {
        "overall": summarise(outcomes),
        "within_capability": summarise(capable),
        "by_category": grouped(outcomes, "category"),
        "by_dialect": grouped(outcomes, "dialect"),
        "by_provenance": grouped(outcomes, "provenance"),
        "by_tier": grouped(outcomes, "tier"),
        "false_negative_examples": [o.id for o in outcomes if o.kind == "fn"][:examples],
        "false_positive_examples": [o.id for o in outcomes if o.kind == "fp"][:examples],
        "decision_mismatch_examples": [
            o.id for o in outcomes if o.expected is not o.actual and o.kind in ("tp", "tn")
        ][:examples],
    }
